//! The engine fixture of the QA harnesses (`qa-overlay.html`,
//! `qa-panel.html`): real `strategic-analysis` payloads, so the headless
//! screenshots in `docs/design/verification/` show the engine's own texts
//! rather than hand-written ones.
//!
//! The fixed-seed cash 6-max and MTT 9-max knockout corpora of
//! `sim_matrix_tests` (baseline profiles of `scripts/sim/profiles.json`) are
//! generated by `scripts/sim/generate.mjs` into a temporary folder and
//! imported into a temporary database. For one full table of each, the
//! overlay's own roster call (`commands::active_table_payloads`) builds the
//! payloads exactly as the app does between hands. The fixture keeps what the
//! HUD, the hover card and the side panel show: name, hands, seat, stats,
//! archetype and the engine's chip tag, top reads and every read with its
//! sample.
//!
//! The test fails when `tests/fixtures/qa_engine_reads.json` differs from
//! that output. To regenerate it after an engine change:
//!
//! ```sh
//! VELORA_QA_FIXTURE_WRITE=1 node scripts/cargo-test-msvc.mjs --features strategic-analysis --test qa_fixture_tests
//! ```
#![cfg(feature = "strategic-analysis")]

use std::path::{Path, PathBuf};
use std::process::Command;

use rusqlite::Connection;
use serde_json::{json, Map, Value};
use velora_poker_lib::commands::active_table_payloads;
use velora_poker_lib::db;
use velora_poker_lib::engine::EngineCache;
use velora_poker_lib::import::import_directory;

/// One QA table: the `sim_matrix_tests` corpus it comes from.
struct QaTable {
    max_players: i64,
    format: &'static str,
    seed: &'static str,
    tables: u32,
    hands: u32,
}

const QA_TABLES: [QaTable; 2] = [
    QaTable { max_players: 6, format: "cash", seed: "matrix-cash", tables: 6, hands: 600 },
    QaTable { max_players: 9, format: "mtt", seed: "matrix-mtt", tables: 4, hands: 400 },
];

const FIXTURE: &str = "tests/fixtures/qa_engine_reads.json";

/// What the harnesses read of each player's payload.
const PLAYER_FIELDS: [&str; 7] = ["name", "hands", "seat", "seatOffset", "stats", "classification", "descriptions"];
const ENGINE_FIELDS: [&str; 4] = ["version", "tag", "topReads", "reads"];

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).parent().expect("repo root").to_path_buf()
}

fn baseline_ids() -> String {
    let text = std::fs::read_to_string(repo_root().join("scripts/sim/profiles.json")).expect("read profiles.json");
    let profiles: Value = serde_json::from_str(&text).expect("profiles.json is JSON");
    let ids: Vec<&str> = profiles["profiles"]
        .as_array()
        .expect("profiles")
        .iter()
        .filter(|p| p.get("engineTargets").is_none())
        .map(|p| p["id"].as_str().unwrap())
        .collect();
    ids.join(",")
}

fn inside(root: &Path, path: &Path) -> bool {
    let root = std::fs::canonicalize(root).expect("canonical temp root");
    std::fs::canonicalize(path).is_ok_and(|p| p.starts_with(&root))
}

/// Generates and imports `table`'s corpus under `root`.
fn corpus(root: &Path, table: &QaTable) -> Connection {
    if let Some(appdata) = std::env::var_os("APPDATA") {
        let real = PathBuf::from(appdata).join("com.velora.poker");
        assert!(!root.starts_with(&real), "the temporary folder is inside the real Velora data folder");
    }
    let out = root.join(table.format).join("HandHistory");
    let output = Command::new("node")
        .current_dir(repo_root())
        .arg("scripts/sim/generate.mjs")
        .args(["--out", out.to_str().expect("utf-8 path"), "--format", table.format, "--seed", table.seed])
        .args(["--tables", &table.tables.to_string(), "--hands", &table.hands.to_string(), "--pace", "0", "--manifest"])
        .args(["--profiles", &baseline_ids()])
        .output()
        .expect("run node scripts/sim/generate.mjs (is node on PATH?)");
    assert!(output.status.success(), "generator failed: {}", String::from_utf8_lossy(&output.stderr));
    assert!(inside(root, &out), "hand histories outside the temporary folder");
    let db_path = root.join(table.format).join("velora.db");
    let mut conn = db::open(&db_path).expect("open temp db");
    conn.execute_batch("PRAGMA synchronous = OFF;").expect("pragma");
    assert!(inside(root, &db_path), "database outside the temporary folder");
    let summary = import_directory(&mut conn, &out).expect("import directory");
    assert_eq!(summary.hands_failed + summary.hands_rejected_invalid, 0, "{}: import failures", table.format);
    conn
}

fn pick(value: &Value, fields: &[&str]) -> Value {
    let mut out = Map::new();
    for field in fields {
        out.insert((*field).to_string(), value.get(*field).cloned().unwrap_or(Value::Null));
    }
    Value::Object(out)
}

/// The roster of `table_name`'s latest hand, by seat, as the overlay
/// receives it. The hero's own payload is kept as the app sends it; the
/// harnesses show opponents' reads only.
fn roster(conn: &Connection, cache: &mut EngineCache, table_name: &str) -> Vec<Value> {
    let payloads = active_table_payloads(conn, cache, Some(table_name), None).expect("active table payloads");
    let mut players: Vec<Value> = payloads
        .iter()
        .map(|p| {
            let full = serde_json::to_value(p).expect("payload JSON");
            let mut player = pick(&full, &PLAYER_FIELDS);
            player["engine"] = match full.get("engine") {
                Some(engine) if !engine.is_null() => pick(engine, &ENGINE_FIELDS),
                _ => Value::Null,
            };
            player
        })
        .collect();
    players.sort_by_key(|p| p["seat"].as_i64());
    players
}

/// A table every harness check can use: all seats taken, the hero seated,
/// and every villain with at least one read, so every chip has a tag and a
/// hover card with the engine's texts.
fn usable(players: &[Value], max_players: i64) -> bool {
    let villains: Vec<&Value> = players.iter().filter(|p| p["seatOffset"].as_i64() != Some(0)).collect();
    players.len() as i64 == max_players
        && villains.len() as i64 == max_players - 1
        && villains.iter().all(|v| {
            v["engine"]["topReads"].as_array().is_some_and(|r| !r.is_empty()) && !v["engine"]["tag"].is_null()
        })
}

fn qa_table(root: &Path, table: &QaTable) -> Value {
    let conn = corpus(root, table);
    let names: Vec<String> = conn
        .prepare("SELECT DISTINCT table_name FROM hands WHERE table_name IS NOT NULL ORDER BY table_name")
        .unwrap()
        .query_map([], |row| row.get(0))
        .unwrap()
        .collect::<Result<_, _>>()
        .unwrap();
    let mut cache = EngineCache::new();
    for name in &names {
        let players = roster(&conn, &mut cache, name);
        if usable(&players, table.max_players) {
            return json!({
                "maxPlayers": table.max_players,
                "format": table.format,
                "corpus": { "seed": table.seed, "tables": table.tables, "hands": table.hands, "profiles": "baseline" },
                "tableName": name,
                "players": players,
            });
        }
    }
    panic!("no {}-max {} table has every seat taken and a read on every villain", table.max_players, table.format);
}

fn fixture() -> Value {
    let tmp = tempfile::tempdir().expect("temp dir");
    let tables: Vec<Value> = QA_TABLES.iter().map(|t| qa_table(tmp.path(), t)).collect();
    json!({
        "about": "Real strategic-analysis payloads for qa-overlay.html and qa-panel.html, generated by src-tauri/tests/qa_fixture_tests.rs from the sim_matrix_tests corpora. Do not edit by hand: regenerate with VELORA_QA_FIXTURE_WRITE=1 node scripts/cargo-test-msvc.mjs --features strategic-analysis --test qa_fixture_tests",
        "tables": tables,
    })
}

#[test]
fn qa_fixture_matches_engine_output() {
    let generated = fixture();
    check_shape(&generated);
    let expected = serde_json::to_string_pretty(&generated).expect("fixture JSON") + "\n";
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join(FIXTURE);
    if std::env::var_os("VELORA_QA_FIXTURE_WRITE").is_some() {
        std::fs::write(&path, &expected).expect("write the QA fixture");
        eprintln!("wrote {}", path.display());
        return;
    }
    let committed = std::fs::read_to_string(&path)
        .unwrap_or_else(|_| panic!("{} is missing; run with VELORA_QA_FIXTURE_WRITE=1 to write it", path.display()))
        .replace("\r\n", "\n");
    assert!(
        committed == expected,
        "{} has drifted from the engine's output; rerun with VELORA_QA_FIXTURE_WRITE=1 and regenerate the QA screenshots",
        path.display()
    );
}

/// The fixture carries what the harness checks depend on.
fn check_shape(fixture: &Value) {
    let tables = fixture["tables"].as_array().expect("tables");
    assert_eq!(tables.iter().map(|t| t["maxPlayers"].as_i64().unwrap()).collect::<Vec<_>>(), vec![6, 9]);
    for table in tables {
        let players = table["players"].as_array().expect("players");
        let max = table["maxPlayers"].as_i64().unwrap();
        assert!(usable(players, max), "{max}-max table no longer usable by the harnesses");
        let hero: Vec<&Value> = players.iter().filter(|p| p["seatOffset"].as_i64() == Some(0)).collect();
        assert_eq!(hero.len(), 1, "{max}-max: one hero");
        for villain in players.iter().filter(|p| p["seatOffset"].as_i64() != Some(0)) {
            let reads = villain["engine"]["reads"].as_array().unwrap();
            let top = villain["engine"]["topReads"].as_array().unwrap();
            assert_eq!(top.as_slice(), &reads[..top.len()], "topReads are the first reads");
            for read in top {
                assert!(!read["observation"].as_str().unwrap().is_empty() && !read["advice"].as_str().unwrap().is_empty());
            }
        }
        assert!(
            players.iter().any(|p| !p["engine"]["topReads"][0]["sample"].is_null()),
            "{max}-max: some top read shows its sample on the chip"
        );
    }
}
